import{c as r}from"./chunk-EUFIJQIT.js";var s={releases:[{date:"2026-08-20",title:{en:"Grimvale opens, everyone dispatches loot, and progress saves itself",pt:"Grimvale abre, todo mundo despacha loot, e o progresso salva sozinho"},sections:[{title:{en:"New hunts",pt:"Novas ca\xE7adas"},notes:[{kind:"new",text:{en:"New hunt \u2014 Grimvale Warrens: the werebadgers' tunnels, between Zao Stronghold and Dragon Lord Peak.",pt:"Nova ca\xE7ada \u2014 Grimvale Warrens: os t\xFAneis dos werebadgers."}},{kind:"new",text:{en:"New hunt \u2014 Grimvale Dens: wereboars and werebears, deeper in the same cave.",pt:"Nova ca\xE7ada \u2014 Grimvale Dens: wereboars e werebears, mais fundo na mesma caverna."}},{kind:"new",text:{en:"The lycanthropes join the bestiary as a class of their own.",pt:"Os licantropos entraram no besti\xE1rio como uma classe pr\xF3pria."}}]},{title:{en:"Loot dispatch",pt:"Dispatch de loot"},notes:[{kind:"new",text:{en:"Every account can now dispatch loot mid-hunt \u2014 a courier sells the marked loot at the city shop and the gold lands at once, while the hunt goes on. Once an hour on a free account, every 30 minutes with premium.",pt:"Toda conta agora pode despachar loot no meio da ca\xE7ada \u2014 um mensageiro vende o loot marcado na loja da cidade e o gold chega na hora, enquanto a ca\xE7ada continua. Uma vez por hora na conta free, a cada 30 minutos com premium."}}]},{title:{en:"Combat",pt:"Combate"},notes:[{kind:"fixed",text:{en:"Health and mana regeneration is now per vocation \u2014 each vocation regenerates the pool it is about \u2014 and the promotion at level 20 is what unlocks the full rate.",pt:"A regenera\xE7\xE3o de vida e mana agora \xE9 por voca\xE7\xE3o \u2014 cada voca\xE7\xE3o regenera mais do que \xE9 a cara dela \u2014 e a promo\xE7\xE3o no n\xEDvel 20 \xE9 o que libera a taxa cheia."}},{kind:"fixed",text:{en:"The great spirit potion arrives \u2014 the paladin's drink at level 80, restoring health and mana in one swallow.",pt:"Chegou a great spirit potion \u2014 a po\xE7\xE3o do paladin n\xEDvel 80, que recupera vida e mana no mesmo gole."}},{kind:"fixed",text:{en:"A character fighting with runes or area spells no longer drops a target its blasts are landing on.",pt:"Um personagem ca\xE7ando com runas ou magias de \xE1rea n\xE3o abandona mais um alvo que os hits est\xE3o acertando."}}]},{title:{en:"Action bar",pt:"Action bar"},notes:[{kind:"new",text:{en:"Shift+click on a slot switches its rule off \u2014 and on again \u2014 without opening the editor.",pt:"Shift+clique num slot desliga a regra \u2014 e religa \u2014 sem abrir o editor."}},{kind:"new",text:{en:"The preset picker gained Clear the bar: one confirmed click empties every slot of the set being worn.",pt:"O menu de presets ganhou a op\xE7\xE3o Limpar a barra: um clique confirmado esvazia todos os slots do set atual."}}]},{title:{en:"Market",pt:"Mercado"},notes:[{kind:"changed",text:{en:"A Huntera Coin offer can no longer cross the standing book \u2014 a sale priced under the best buy is refused instead of filled at a mistake's price.",pt:"Uma oferta de Huntera Coins n\xE3o pode mais cruzar o livro, uma venda abaixo da melhor compra \xE9 recusada em vez de executada no pre\xE7o errado."}},{kind:"changed",text:{en:"Every coin offer and purchase reads its numbers back and asks for a confirmation, and buying starts at 1 coin instead of the whole lot.",pt:"Toda oferta e compra de coins repete os n\xFAmeros e pede confirma\xE7\xE3o, e a compra come\xE7a em 1 coin em vez do lote inteiro."}},{kind:"fixed",text:{en:"Rings and amulets can be listed on the auction again \u2014 a brand-new copy was being treated as a worn one.",pt:"An\xE9is e amuletos voltaram a poder ser vendidos no leil\xE3o \u2014 uma c\xF3pia nova estava sendo tratada como usada."}}]},{title:{en:"Guilds",pt:"Guildas"},notes:[{kind:"improved",text:{en:"The roster ranks by contribution \u2014 leader, vices, then whoever gave the most \u2014 and stops reshuffling whenever someone logs in.",pt:"A lista da guild agora ordena por contribui\xE7\xE3o \u2014 l\xEDder, vices, e depois quem mais contribuiu \u2014 e parou de embaralhar quando algu\xE9m loga."}},{kind:"fixed",text:{en:"An expedition only asks for creatures some hunt actually fields.",pt:"A expedi\xE7\xE3o s\xF3 pede criaturas que existem em alguma ca\xE7ada."}},{kind:"fixed",text:{en:"Joining a friend on a busy world stopped refusing when there was room, and a refused invite can be tried again instead of vanishing with the answer.",pt:"Entrar no mundo de um amigo parou de recusar quando havia espa\xE7o, e um convite recusado pode ser tentado de novo em vez de sumir junto com a resposta."}}]},{title:{en:"Chat",pt:"Chat"},notes:[{kind:"new",text:{en:"A System tab keeps the notices the top of the screen takes away \u2014 level ups, skill advances and announcements can be read after the banner is gone.",pt:"Uma aba System guarda os avisos que somem do topo da tela \u2014 level up, skill e an\xFAncios podem ser lidos depois que o banner sumiu."}},{kind:"new",text:{en:"[Huntera - Infos] speaks on global chat from time to time \u2014 the house's standing notices, on a rotation. No player can wear that name.",pt:"[Huntera - Infos] fala no chat global de tempos em tempos \u2014 avisos fixos da casa, em rod\xEDzio. Nenhum jogador pode usar esse nome."}}]},{title:{en:"Interface",pt:"Interface"},notes:[{kind:"improved",text:{en:"The character-select screen becomes pages, with a name search, a vocation filter and sorting \u2014 an account with hundreds of characters opens instantly.",pt:"A sele\xE7\xE3o de personagens virou p\xE1ginas, com busca por nome, filtro de voca\xE7\xE3o e ordena\xE7\xE3o."}},{kind:"fixed",text:{en:"The Arena tab stopped jumping back to the top of the pit list mid-combat.",pt:"A aba de Arena parou de voltar para o topo da lista durante o combate."}}]},{title:{en:"Saving and worlds",pt:"Salvamento e mundos"},notes:[{kind:"improved",text:{en:"Progress now saves itself every 30 seconds and the inventory within a minute of changing \u2014 a crash costs seconds, not minutes.",pt:"Corrigido um problema com o salvamento de algumas contas durante server saves."}},{kind:"changed",text:{en:"The depot gets a ceiling: 1,000 distinct item kinds, with a counter shown once it is 80% full. Nothing already stored is ever taken.",pt:"O depot ganhou um limite: 1.000 tipos de itens diferentes, com um contador exibido a partir de 80%. Nada que j\xE1 est\xE1 guardado \xE9 removido."}},{kind:"fixed",text:{en:"A crowd logging in at the same moment spreads across the worlds instead of piling onto one.",pt:"Uma multid\xE3o logando ao mesmo tempo se espalha entre os mundos em vez de encher um s\xF3."}}]}]},{date:"2026-08-19",title:{en:"Three new hunts in Yalahar, and the magic shield on the mana bar",pt:"Tr\xEAs ca\xE7adas novas em Yalahar, e o magic shield na barra de mana"},sections:[{title:{en:"Combat",pt:"Combate"},notes:[{kind:"new",text:{en:"The magic shield now reads on the mana bar, so how much of it is left is visible at a glance.",pt:"Atualizada a visualiza\xE7\xE3o do magic shield na barra de mana para facilitar entender como est\xE1 funcionando a defesa."}},{kind:"fixed",text:{en:"Fixed the area effect of Diamond Arrows.",pt:"Corrigido efeito de \xE1rea das Diamond Arrows."}},{kind:"new",text:{en:"Some spells take a new action-bar condition: WHEN PARALYZED.",pt:"Adicionado nova condi\xE7\xE3o em algumas spells: QUANDO PARALIZADO."}},{kind:"fixed",text:{en:"Fixed a bug that kept some support spells from being cast again over themselves (haste/utani hur).",pt:"Corrigido um bug que impedia algumas magias de suporte n\xE3o aplicarem novamente (haste/utani hur)."}},{kind:"fixed",text:{en:"Fixed the life and mana leech imbuements on armors and helmets.",pt:"Corrigido efeito dos imbuements de life/mana leech nas armaduras/elmos."}}]},{title:{en:"Hunting and prey",pt:"Ca\xE7adas e prey"},notes:[{kind:"new",text:{en:"New hunt \u2014 Yalahar Bog: a flooded quarter draining under the city, held by bog raiders.",pt:"Nova ca\xE7ada \u2014 Yalahar Bog: um alagado que corre sob a cidade, tomado por bog raiders."}},{kind:"new",text:{en:"New hunt \u2014 Yalahar Green Djinn Fortress: a walled keep of four floors in the middle of the city, with the gate standing open.",pt:"Nova ca\xE7ada \u2014 Yalahar Green Djinn Fortress: uma fortaleza murada de quatro andares no meio da cidade, com o port\xE3o aberto."}},{kind:"new",text:{en:"New hunt \u2014 Yalahar Blue Djinn Fortress: the rival keep across the magicians' quarter, six floors climbed from the street. The same casts as the green djinn, but they answer to different things.",pt:"Nova ca\xE7ada \u2014 Yalahar Blue Djinn Fortress: a fortaleza rival do outro lado do bairro dos magos, seis andares subindo da rua. As mesmas magias dos green djinn, mas com fraquezas diferentes."}},{kind:"improved",text:{en:"The Vampire Crypt's deeper vaults now belong to the Vampire Viscount and the Vampire Bride. The opening vaults are the two plain vampires they always were.",pt:"As criptas mais profundas do Vampire Crypt agora s\xE3o dos Vampire Viscounts e das Vampire Brides. As primeiras continuam com os vampiros de sempre."}},{kind:"fixed",text:{en:"Fixed a case where prey could offer a creature that no hunt actually spawns.",pt:"Corrigido uma situa\xE7\xE3o onde o sistema de prey podia exibir um monstro sem hunt dispon\xEDvel."}}]},{title:{en:"Market",pt:"Mercado"},notes:[{kind:"new",text:{en:"An item's auction can now be opened straight from the right-click menu in the city.",pt:"Adicionado a op\xE7\xE3o de abrir o leil\xE3o de um item atrav\xE9s do menu com clique direito na cidade."}},{kind:"improved",text:{en:"Buying an auction offer now starts at one piece instead of the whole stack.",pt:"Ativar a compra de um item no leil\xE3o agora tem a quantidade inicial 1 ao inv\xE9s de quantidade m\xE1xima."}},{kind:"fixed",text:{en:"The auction stopped resetting itself while a training session is running.",pt:"O leil\xE3o parou de se reiniciar sozinho enquanto uma sess\xE3o de treino est\xE1 rolando."}}]},{title:{en:"Guilds",pt:"Guildas"},notes:[{kind:"new",text:{en:"The guild window's expeditions can be detached on their own, to keep the day's expeditions on screen.",pt:"Agora \xE9 poss\xEDvel destacar apenas a se\xE7\xE3o de expedi\xE7\xE3o da janela da guild para facilitar o acompanhamento das expedi\xE7\xF5es."}},{kind:"fixed",text:{en:"Fixed a bug where the guild took too long to roll the creatures available for expeditions.",pt:"Corrigido um bug onde a guild estava demorando para renovar os monstros dispon\xEDveis para expedi\xE7\xE3o."}},{kind:"fixed",text:{en:"A guild member now always tries to enter the same world instance their guildmates are in.",pt:"Um membro de guild sempre vai tentar entrar na mesma inst\xE2ncia de mundo em que os companheiros de guild est\xE3o."}}]},{title:{en:"Store and mounts",pt:"Loja e montarias"},notes:[{kind:"new",text:{en:"The mount shelf opens by saying what riding actually gives you.",pt:"A prateleira de montarias abre dizendo o que montar realmente d\xE1."}}]},{title:{en:"Items and depot",pt:"Itens e depot"},notes:[{kind:"fixed",text:{en:"Fixed a problem where equipping a ring with a sale lock equipped the whole stack.",pt:"Corrigido um problema ao equipar a pilha inteira de an\xE9is ao equipar um anel com bloqueio de venda."}},{kind:"fixed",text:{en:"Fixed a bug where taking a whole stack out of the depot moved only a single item.",pt:"Corrigido um bug onde ao tentar retirar todo o stack de um item do depot, estava retirando apenas uma unidade."}}]},{title:{en:"Wiki",pt:"Wiki"},notes:[{kind:"new",text:{en:"The News tab shows one update at a time, picked off a timeline with every earlier one beside it.",pt:"A aba de Novidades mostra uma atualiza\xE7\xE3o por vez, escolhida numa linha do tempo com todas as anteriores ao lado."}},{kind:"improved",text:{en:"In the bestiary, all entries now means all creatures, not all classes.",pt:"No besti\xE1rio, todas as entradas agora significa todas as criaturas, e n\xE3o todas as classes."}},{kind:"fixed",text:{en:"Fixed a visual bug in the bestiary window.",pt:"Corrigido um bug visual na janela de besti\xE1rio."}}]},{title:{en:"Training, chat and accounts",pt:"Treino, chat e contas"},notes:[{kind:"improved",text:{en:"The exercise shield is sold again at both counters \u2014 the city shop and the coin store.",pt:"Adicionado exercise shield \xE0 loja de NPC e store."}},{kind:"fixed",text:{en:"Fixed a case where two characters on the same account could be online at the same time.",pt:"Corrigido uma situa\xE7\xE3o onde players de mesma account conseguiam entrar ao mesmo tempo."}}]}]},{date:"2026-08-18",title:{en:"A clearer action bar and a wider coin store",pt:"Uma action bar mais clara e uma loja de coins maior"},sections:[{title:{en:"Hunting",pt:"Ca\xE7adas"},notes:[{kind:"new",text:{en:"The creature card in a hunt's roster now carries your bestiary standing, so you can tell at a glance whether you still need kills there.",pt:"O card da criatura na lista da ca\xE7ada agora mostra o seu progresso de bestiary, ent\xE3o d\xE1 para ver de relance se voc\xEA ainda precisa de kills ali."}},{kind:"new",text:{en:"A hunt can now end itself when a party member stops hunting \u2014 a party that arrives together leaves together.",pt:"A ca\xE7ada agora pode se encerrar sozinha quando algu\xE9m da party para de ca\xE7ar \u2014 quem chega junto, sai junto."}},{kind:"improved",text:{en:`"Your best" moved up under the hunt's name, where it is the first thing read about a hunt you have already run.`,pt:'O "Seu recorde" subiu para logo abaixo do nome da ca\xE7ada, que \xE9 a primeira coisa que se olha numa ca\xE7ada j\xE1 feita.'}},{kind:"improved",text:{en:"The hunt window stays readable while a hunt is running.",pt:"A janela de ca\xE7ada continua leg\xEDvel enquanto a ca\xE7ada est\xE1 rolando."}}]},{title:{en:"Combat",pt:"Combate"},notes:[{kind:"new",text:{en:"An action bar slot held back by another action's condition now says why it will not fire.",pt:"Uma a\xE7\xE3o na action bar que esbarra na condi\xE7\xE3o de outra agora informa o motivo de n\xE3o ser usada."}}]},{title:{en:"Training",pt:"Treino"},notes:[{kind:"new",text:{en:"Training is no longer open to a character who has not been given a vocation yet.",pt:"N\xE3o \xE9 mais poss\xEDvel treinar sem ter recebido a voca\xE7\xE3o."}}]},{title:{en:"Chat, party and guilds",pt:"Chat, party e guildas"},notes:[{kind:"new",text:{en:"Chat names a speaker by level and vocation.",pt:"O chat identifica quem fala por n\xEDvel e voca\xE7\xE3o."}},{kind:"new",text:{en:"Guild chat colours each message by the rank of the person writing it.",pt:"Cores diferentes para mensagens no chat da guild conforme o cargo de quem est\xE1 falando."}},{kind:"fixed",text:{en:"Fixed the text fields in the guild window locking up.",pt:"Corrigido um bug onde os campos de texto durante a janela da guild estavam travando."}}]},{title:{en:"Store and market",pt:"Loja e mercado"},notes:[{kind:"changed",text:{en:"The coin store grew a second row of packages, up to 20,000 Huntera Coins.",pt:"A loja de coins ganhou uma segunda fileira de pacotes, at\xE9 20.000 Huntera Coins."}},{kind:"changed",text:{en:"Only premium accounts can place offers in the auction.",pt:"Apenas premium accounts podem inserir ofertas no leil\xE3o."}}]},{title:{en:"Items and interface",pt:"Itens e interface"},notes:[{kind:"improved",text:{en:"Rings and amulets now show their charges as a bar across the item's icon, so a stack is free to show how many it holds again.",pt:"An\xE9is e amuletos agora exibem suas cargas por uma barra de progresso no \xEDcone do item. Quantidades estacadas agora s\xE3o formadas pelos n\xFAmeros."}}]},{title:{en:"Reports and worlds",pt:"Den\xFAncias e mundos"},notes:[{kind:"new",text:{en:"Misconduct in chat can now be reported. Be careful what you accuse someone of \u2014 a false report is itself a bannable offence.",pt:"Agora \xE9 poss\xEDvel denunciar alguma conduta incorreta no chat. Cuidado para n\xE3o fazer falsas acusa\xE7\xF5es ou vai acabar sendo banido."}},{kind:"fixed",text:{en:`Accepting a friend's invite stopped answering "there is no room" for a world with room to spare.`,pt:'Aceitar o convite de um amigo parou de responder "n\xE3o h\xE1 espa\xE7o" num mundo com espa\xE7o de sobra.'}}]}]},{date:"2026-08-17",title:{en:"Three new hunts, the party roster and guild expeditions",pt:"Tr\xEAs ca\xE7adas novas, a lista da party e as expedi\xE7\xF5es de guilda"},sections:[{title:{en:"New hunts",pt:"Novas ca\xE7adas"},notes:[{kind:"new",text:{en:"The corym warren opens beneath Carlin.",pt:"O covil dos corym abre debaixo de Carlin."}},{kind:"new",text:{en:"The elf quarter and the Dark Cathedral open their gates.",pt:"O bairro \xE9lfico e a Catedral Sombria abrem os port\xF5es."}},{kind:"new",text:{en:"New creatures joined the bestiary: the corym line, the elf arcanist and the cathedral's five humans.",pt:"Novas criaturas entraram no bestiary: a linha corym, o elf arcanist e os cinco humanos da catedral."}},{kind:"improved",text:{en:"A species out of your reach is greyed out on a hunt's roster instead of being cut from it.",pt:"Uma esp\xE9cie fora do seu alcance aparece em cinza na lista da ca\xE7ada, em vez de sumir dela."}}]},{title:{en:"Party and guilds",pt:"Party e guildas"},notes:[{kind:"new",text:{en:"The party roster shows every member's level, health and mana, and the party got a chat channel of its own.",pt:"A lista da party mostra o n\xEDvel, a vida e a mana de cada membro, e a party ganhou um canal de chat pr\xF3prio."}}]},{title:{en:"Market, trade and shop",pt:"Mercado, trade e loja"},notes:[{kind:"new",text:{en:"An item on the auction can now be inspected for its attributes.",pt:"Agora \xE9 poss\xEDvel inspecionar os atributos dos itens no leil\xE3o."}},{kind:"improved",text:{en:"Potions now say how much they restore.",pt:"As po\xE7\xF5es agora informam o poder de recupera\xE7\xE3o."}},{kind:"fixed",text:{en:"Fixed the selling price of some items.",pt:"Corrigido o pre\xE7o de venda de alguns itens."}}]},{title:{en:"Interface and phones",pt:"Interface e celular"},notes:[{kind:"new",text:{en:'The ticket window has a "My tickets" tab: what you sent, and the answer written back to it.',pt:'A janela de tickets tem a aba "Meus tickets": o que voc\xEA enviou, e a resposta escrita de volta.'}},{kind:"improved",text:{en:"The guided start can be finished on a phone, and the phone header says how many are online.",pt:"O in\xEDcio guiado d\xE1 para terminar no celular, e o topo no celular diz quantos est\xE3o online."}},{kind:"improved",text:{en:"The chat panel opens on the room that has people in it.",pt:"O painel de chat abre na sala que tem gente."}},{kind:"improved",text:{en:"Dropping an item onto a taken action slot asks whether to swap or to insert.",pt:"Soltar um item num slot de a\xE7\xE3o j\xE1 ocupado pergunta se \xE9 para trocar ou inserir."}},{kind:"fixed",text:{en:"The prey reroll button quotes the level you are now, and a friend's level on the list moves the moment it moves.",pt:"O bot\xE3o de reroll de prey cita o n\xEDvel que voc\xEA tem agora, e o n\xEDvel de um amigo na lista muda no instante em que muda."}}]}]}]};var d=["new","improved","fixed","balance","changed"],h={new:"patch::New",improved:"patch::Improved",fixed:"patch::Fixed",balance:"patch::Balance",changed:"patch::Changed"},c=s.releases;function g(a){return r()==="pt-BR"&&a.pt.trim()!==""?a.pt:a.en}var l="tibia-web.patchNotesSeen";function f(){let a=c[0]?.date;if(a!==void 0)try{localStorage.setItem(l,a)}catch{}}function w(a,n){let[t,e,o]=a.split("-").map(Number);return!t||!e||!o?a:new Date(t,e-1,o).toLocaleDateString(n,{day:"numeric",month:"long",year:"numeric"})}function b(a,n){let[t,e,o]=a.split("-").map(Number);return!t||!e||!o?a:new Date(t,e-1,o).toLocaleDateString(n,{day:"numeric",month:"short",year:"numeric"})}function v(a){let n=e=>typeof e=="object"&&e!==null&&typeof e.en=="string"&&typeof e.pt=="string";if(typeof a!="object"||a===null)throw new Error("not an object");let t=a.releases;if(!Array.isArray(t))throw new Error("no releases array");for(let e of t){if(!/^\d{4}-\d{2}-\d{2}$/.test(e?.date??""))throw new Error(`release date must be YYYY-MM-DD, got ${JSON.stringify(e?.date)}`);if(!n(e.title))throw new Error(`release ${e.date}: bad title`);if(!Array.isArray(e.sections))throw new Error(`release ${e.date}: no sections`);for(let o of e.sections){if(!n(o?.title))throw new Error(`release ${e.date}: bad section title`);if(!Array.isArray(o.notes))throw new Error(`release ${e.date}: no notes`);for(let i of o.notes){if(!d.includes(i?.kind))throw new Error(`release ${e.date}: unknown tag ${JSON.stringify(i?.kind)}`);if(!n(i.text))throw new Error(`release ${e.date}: bad note text`)}}}return{releases:t}}export{s as a,d as b,h as c,c as d,g as e,f,w as g,b as h,v as i};
